var url=source.key;
var fl=url+"/xclass/0/1.html";
var ph=url+"/ph/week.html";
var qb=url+"/quanben.html";
var html=java.ajax(fl);
var src=java.ajax(ph);
var qbl=java.ajax(qb);

if(html&&src&&qbl){
a=org.jsoup.Jsoup.parse(html).select(".sortChannel_nav a");
b=org.jsoup.Jsoup.parse(src).select(".sortChannel_nav a");
c=org.jsoup.Jsoup.parse(qbl).select(".sortChannel_nav a");
push("🌹分类🌹",null,1)
    for(i in a){
        title=a[i].text()
        url=a[i].attr("href")
        size=0.25;
  url=String(url).replace("1.html","{{page}}.html")
        push(title,url,size)
    };
 push("🌹排行🌹",null,1)
    for(i in b){
        title=b[i].text()
        url=b[i].attr("href")
  url=String(url).replace(".html","<,_{{page}}>.html")
        size=0.25;
        push(title,url,size)
    }

   push("🌹完本🌹",null,1)
    for(i in c){
        title=c[i].text()
        url=c[i].attr("href")
  url=String(url).replace(".html","<,_{{page}}>.html")
        size=0.25;
        push(title,url,size)
    }

}else{
  java.toast("发现列表获取失败！")
}

JSON.stringify(sort)

@js:
var result = [];
var areas = ['韩国','日本','中国'];
var fulls = [{id:'4',name:'连载中'},{id:'1',name:'已完结'}];

// 默认全部
result.push({
  title: '最新更新',
  url: '/api/comic/index/lists,{"method":"POST","body":"area=9&tags=全部&full=3&page={{page}}"}',
  style: {layout_flexGrow: 1, layout_flexBasisPercent: 1}
});

// 按地区
for (var i = 0; i < areas.length; i++) {
  result.push({
    title: areas[i],
    url: '/api/comic/index/lists,{"method":"POST","body":"area=' + (i+1) + '&tags=全部&full=3&page={{page}}"}',
    style: {layout_flexGrow: 1, layout_flexBasisPercent: 0.25}
  });
}

// 按进度
for (var i = 0; i < fulls.length; i++) {
  result.push({
    title: fulls[i].name,
    url: '/api/comic/index/lists,{"method":"POST","body":"area=9&tags=全部&full=' + fulls[i].id + '&page={{page}}"}',
    style: {layout_flexGrow: 1, layout_flexBasisPercent: 0.25}
  });
}

// 组合
result.push({
  title: '韩国连载中',
  url: '/api/comic/index/lists,{"method":"POST","body":"area=1&tags=全部&full=4&page={{page}}"}'
});
result.push({
  title: '日本连载中',
  url: '/api/comic/index/lists,{"method":"POST","body":"area=2&tags=全部&full=4&page={{page}}"}'
});

JSON.stringify(result);

